// ============================================================
//              SMART GAS STATION         
// ============================================================

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Servo.h>
#include <Keypad.h>

// ============================================================
// LCD
// ============================================================

LiquidCrystal_I2C lcd(0x27, 16, 2);

// ============================================================
// SERVO
// ============================================================

Servo gateServo;

#define SERVO_GATE 11

// ============================================================
// KEYPAD 4x4
// ============================================================

const byte ROWS = 4;
const byte COLS = 4;

char keys[ROWS][COLS] = {
  {'1','2','3','A'},
  {'4','5','6','B'},
  {'7','8','9','C'},
  {'*','0','#','D'}
};

byte rowPins[ROWS] = {
  28, 29, 30, 31
};

byte colPins[COLS] = {
  32, 33, 34, 35
};

Keypad keypad = Keypad(
  makeKeymap(keys),
  rowPins,
  colPins,
  ROWS,
  COLS
);

// ============================================================
// SENSORS
// ============================================================

#define NTC_PIN      A8
#define MQ2_PIN      A9

#define FUEL_TRIG    9
#define FUEL_ECHO    10

#define PIR_ENTRY    2
#define PIR_EXIT     3

// ============================================================
// LEDs + BUZZER
// ============================================================

#define LED_GREEN_PIN   5
#define LED_YELLOW_PIN  6
#define LED_RED_PIN     13

#define BUZZER_PIN      12

// ============================================================
// STEPPER 1 = FUEL PUMP
// ============================================================

#define STEP1 22
#define DIR1  23
#define EN1   24

// ============================================================
// STEPPER 2 = VENTILATION FAN
// ============================================================

#define STEP2 25
#define DIR2  26
#define EN2   27

// ============================================================
// BUTTONS
// ============================================================

#define BTN_EMERGENCY 36
#define BTN_HALL      37

// ============================================================
// NTC
// ============================================================

#define SERIES_RESISTOR 10000.0
#define NTC_NOMINAL     10000.0
#define NTC_BETA        3950.0

// ============================================================
// SYSTEM STATES
// ============================================================

enum SystemState {
  SAFE,
  WARNING,
  DANGER
};

SystemState currentState = SAFE;

// ============================================================
// VARIABLES
// ============================================================

float temperature = 0.0;

int gasValue = 0;
int fuelDistance = 0;

bool systemRunning = true;

bool gateOpen = false;

bool pumpRunning = false;

// ============================================================
// GAS THRESHOLDS
// ============================================================
const int GAS_WARNING = 300;
const int GAS_DANGER  = 700;

// Temperature thresholds

const float TEMP_WARNING = 25.0;
const float TEMP_DANGER  = 40.0;

// ============================================================
// PASSWORD
// ============================================================

String enteredPassword = "";

const String correctPassword = "4321";

// ============================================================
// KEYPAD DISPLAY
// ============================================================

bool keypadActive = false;

unsigned long keypadLastTime = 0;

const unsigned long KEYPAD_TIMEOUT = 3000;
 // ============================================================
// GATE
// ============================================================

volatile bool entryDetected = false;
volatile bool exitDetected = false;

bool gateOpening = false;

unsigned long gateOpenTime = 0;

const unsigned long GATE_OPEN_TIME = 5000;

// ============================================================
// PUMP
// ============================================================

unsigned long pumpStartTime = 0;

const unsigned long PUMP_TIME = 5000;

unsigned long lastPumpStep = 0;

const unsigned long PUMP_STEP_INTERVAL = 1000;

// ============================================================
// FAN
// ============================================================

unsigned long lastFanStep = 0;

const unsigned long FAN_STEP_INTERVAL = 1000;

// ============================================================
// LCD
// ============================================================

unsigned long lastLCD = 0;

const unsigned long LCD_INTERVAL = 700;

// ============================================================
// EMERGENCY
// ============================================================

bool lastEmergencyButton = HIGH;

// ============================================================
// SETUP
// ============================================================

void setup() {

  // ---------------- LCD ----------------

  lcd.init();
  lcd.backlight();

  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("SMART GAS");

  lcd.setCursor(0, 1);
  lcd.print("STATION");

  delay(1500);

  // ---------------- SERVO ----------------

  gateServo.attach(SERVO_GATE);

  gateServo.write(0);

  // ---------------- SENSORS ----------------

  pinMode(NTC_PIN, INPUT);
  pinMode(MQ2_PIN, INPUT);

  pinMode(FUEL_TRIG, OUTPUT);
  pinMode(FUEL_ECHO, INPUT);

  pinMode(PIR_ENTRY, INPUT_PULLUP);
  pinMode(PIR_EXIT, INPUT_PULLUP);

  // ---------------- BUTTONS ----------------

  pinMode(BTN_EMERGENCY, INPUT_PULLUP);
  pinMode(BTN_HALL, INPUT_PULLUP);

  // ---------------- LEDs ----------------

  pinMode(LED_GREEN_PIN, OUTPUT);
  pinMode(LED_YELLOW_PIN, OUTPUT);
  pinMode(LED_RED_PIN, OUTPUT);

  // ---------------- BUZZER ----------------

  pinMode(BUZZER_PIN, OUTPUT);

  noTone(BUZZER_PIN);

  // ---------------- STEPPER 1 ----------------

  pinMode(STEP1, OUTPUT);
  pinMode(DIR1, OUTPUT);
  pinMode(EN1, OUTPUT);

  // ---------------- STEPPER 2 ----------------

  pinMode(STEP2, OUTPUT);
  pinMode(DIR2, OUTPUT);
  pinMode(EN2, OUTPUT);

  // A4988 ENABLE = LOW means enabled

  digitalWrite(EN1, HIGH);
  digitalWrite(EN2, HIGH);

  digitalWrite(STEP1, LOW);
  digitalWrite(STEP2, LOW);

  digitalWrite(DIR1, LOW);
  digitalWrite(DIR2, LOW);

  // ---------------- INTERRUPTS ----------------

  attachInterrupt(
    digitalPinToInterrupt(PIR_ENTRY),
    entryISR,
    RISING
  );

  attachInterrupt(
    digitalPinToInterrupt(PIR_EXIT),
    exitISR,
    RISING
  );

  // ---------------- INITIAL STATE ----------------

  setState(SAFE);

  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("SYSTEM READY");

  delay(1000);

  lcd.clear();
}

// ============================================================
// INTERRUPTS
// ============================================================

void entryISR() {

  entryDetected = true;
}

void exitISR() {

  exitDetected = true;
}

// ============================================================
// READ TEMPERATURE
// ============================================================

float readTemperature() {

  int raw = analogRead(NTC_PIN);

  if (raw <= 0)
    raw = 1;

  if (raw >= 1023)
    raw = 1022;

  float resistance =
    SERIES_RESISTOR /
    (1023.0 / raw - 1.0);

  float steinhart =
    log(resistance / NTC_NOMINAL);

  steinhart /= NTC_BETA;

  steinhart +=
    1.0 / (25.0 + 273.15);

  steinhart =
    1.0 / steinhart;

  steinhart -= 273.15;

  return steinhart;
}

// ============================================================
// READ GAS
// ============================================================

int readGas() {
 return analogRead(MQ2_PIN);
}

// ============================================================
// READ FUEL DISTANCE
// ============================================================

int readFuelDistance() {

  digitalWrite(FUEL_TRIG, LOW);

  delayMicroseconds(2);

  digitalWrite(FUEL_TRIG, HIGH);

  delayMicroseconds(10);

  digitalWrite(FUEL_TRIG, LOW);

  unsigned long duration =
    pulseIn(
      FUEL_ECHO,
      HIGH,
      30000
    );

  if (duration == 0)
    return 999;

  return duration * 0.034 / 2;
}

// ============================================================
// CALCULATE STATE
// ============================================================

SystemState calculateState() {

  // DANGER
  if (
    gasValue >= GAS_DANGER ||
    temperature >= TEMP_DANGER
  ) {

    return DANGER;
  }

  // WARNING
  if (
    gasValue >= GAS_WARNING ||
    temperature >= TEMP_WARNING
  ) {

    return WARNING;
  }

  // SAFE
  return SAFE;
}

// ============================================================
// LED CONTROL
// ============================================================

void setLEDs(
  bool green,
  bool yellow,
  bool red
) {

  digitalWrite(
    LED_GREEN_PIN,
    green
  );

  digitalWrite(
    LED_YELLOW_PIN,
    yellow
  );

  digitalWrite(
    LED_RED_PIN,
    red
  );
}

// ============================================================
// CHANGE SYSTEM STATE
// ============================================================

void setState(
  SystemState newState
) {

  currentState = newState;

  // ---------------- SAFE ----------------

  if (currentState == SAFE) {

    setLEDs(
      true,
      false,
      false
    );

    noTone(BUZZER_PIN);

    stopFan();
  }

  // ---------------- WARNING ----------------

  else if (currentState == WARNING) {

    setLEDs(
      false,
      true,
      false
    );

    noTone(BUZZER_PIN);

    startFan();
  }

  // ---------------- DANGER ----------------

  else {

    setLEDs(
      false,
      false,
      true
    );

    tone(
      BUZZER_PIN,
      1000
    );

    startFan();

    // Safety:

    stopPump();
  }
}

// ============================================================
// START FAN
// ============================================================

void startFan() {

  digitalWrite(
    EN2,
    LOW
  );

  digitalWrite(
    DIR2,
    LOW
  );
}

// ============================================================
// STOP FAN
// ============================================================

void stopFan() {

  digitalWrite(
    EN2,
    HIGH
  );

  digitalWrite(
    STEP2,
    LOW
  );
}

// ============================================================
// UPDATE FAN
// ============================================================

void updateFan() {

  if (
    currentState != WARNING &&
    currentState != DANGER
  ) {

    stopFan();

    return;
  }

  unsigned long now =
    micros();

  if (
    now - lastFanStep >=
    FAN_STEP_INTERVAL
  ) {

    lastFanStep = now;

    digitalWrite(
      STEP2,
      HIGH
    );

    delayMicroseconds(300);

    digitalWrite(
      STEP2,
      LOW
    );
  }
}

// ============================================================
// OPEN GATE
// ============================================================

void openGate() {

  gateServo.write(90);

  gateOpen = true;

  gateOpening = true;

  gateOpenTime = millis();
}

// ============================================================
// CLOSE GATE
// ============================================================

void closeGate() {

  gateServo.write(0);

  gateOpen = false;

  gateOpening = false;
}

// ============================================================
// HANDLE GATE
// ============================================================

void handleGate() {

  // Car detected at entrance

  if (entryDetected) {

    entryDetected = false;

    openGate();
  }

  // Exit sensor

  if (exitDetected) {

    exitDetected = false;

    if (gateOpen) {

      gateOpenTime =
        millis();
    }
  }

  // Hall button
 if (
    digitalRead(BTN_HALL) == LOW
  ) {

    openGate();
  }

  // Automatic close

  if (
    gateOpening &&
    millis() - gateOpenTime >=
    GATE_OPEN_TIME
  ) {

    closeGate();
  }
}

// ============================================================
// START PUMP
// ============================================================

void startPump() {

  // Pump cannot work during danger

  if (currentState == DANGER) {

    lcd.clear();

    lcd.setCursor(0, 0);
    lcd.print("DANGER!");

    lcd.setCursor(0, 1);
    lcd.print("PUMP BLOCKED");

    keypadActive = true;

    keypadLastTime =
      millis();

    return;
  }

  if (!gateOpen) {

    lcd.clear();

    lcd.setCursor(0, 0);
    lcd.print("OPEN GATE");

    lcd.setCursor(0, 1);
    lcd.print("FIRST");

    keypadActive = true;

    keypadLastTime =
      millis();

    return;
  }

  // Start pump

  pumpRunning = true;

  pumpStartTime =
    millis();

  lastPumpStep =
    micros();

  digitalWrite(
    EN1,
    LOW
  );

  digitalWrite(
    DIR1,
    LOW
  );

  lcd.clear();

  lcd.setCursor(0, 0);
  lcd.print("ACCESS GRANTED");

  lcd.setCursor(0, 1);
  lcd.print("PUMP ACTIVE");

  keypadActive = true;

  keypadLastTime =
    millis();
}

// ============================================================
// STOP PUMP
// ============================================================

void stopPump() {

  pumpRunning = false;

  digitalWrite(
    EN1,
    HIGH
  );

  digitalWrite(
    STEP1,
    LOW
  );
}

// ============================================================
// UPDATE PUMP
// ============================================================

void updatePump() {

  if (!pumpRunning)
    return;

  // Safety

  if (currentState == DANGER) {

    stopPump();

    return;
  }

  // Generate step pulses

  unsigned long now =
    micros();

  if (
    now - lastPumpStep >=
    PUMP_STEP_INTERVAL
  ) {

    lastPumpStep = now;

    digitalWrite(
      STEP1,
      HIGH
    );

    delayMicroseconds(300);

    digitalWrite(
      STEP1,
      LOW
    );
  }

  // Stop after 5 seconds

  if (
    millis() - pumpStartTime >=
    PUMP_TIME
  ) {

    stopPump();

    lcd.clear();

    lcd.setCursor(0, 0);
    lcd.print("PUMP FINISHED");

    keypadActive = true;

    keypadLastTime =
      millis();
  }
}

// ============================================================
// KEYPAD
// ============================================================

void handleKeypad() {

  char key =
    keypad.getKey();

  if (!key)
    return;

  keypadActive = true;

  keypadLastTime =
    millis();

  // ==========================================================
  // CLEAR
  // ==========================================================

  if (key == '*') {

    enteredPassword = "";

    lcd.clear();

    lcd.setCursor(0, 0);
    lcd.print("ENTER PASSWORD");

    lcd.setCursor(0, 1);
    lcd.print("CLEARED");

    return;
  }

  // ==========================================================
  // ENTER
  // ==========================================================

  if (key == '#') {

    lcd.clear();

    // Correct password

    if (
      enteredPassword ==
      correctPassword
    ) {

      lcd.setCursor(0, 0);
      lcd.print("PASSWORD OK");

      lcd.setCursor(0, 1);
      lcd.print("CHECKING...");

      delay(700);

      startPump();
    }

    // Wrong password

    else {

      lcd.setCursor(0, 0);
      lcd.print("WRONG PASSWORD");

      lcd.setCursor(0, 1);
      lcd.print("TRY AGAIN");

      delay(1000);

      lcd.clear();
    }

    enteredPassword = "";

    keypadLastTime =
      millis();

    return;
  }

  // ==========================================================
  // NUMBER / LETTER
  // ==========================================================

  if (
    enteredPassword.length() < 8
  ) {

    enteredPassword += key;

    lcd.clear();

    lcd.setCursor(0, 0);
    lcd.print("ENTER PASSWORD");

    lcd.setCursor(0, 1);
    lcd.print("PASS:");

    // Display stars
 for (
      unsigned int i = 0;
      i < enteredPassword.length();
      i++
    ) {

      lcd.print('*');
    }
  }
}

// ============================================================
// UPDATE LCD
// ============================================================

void updateLCD() {

  // Don't overwrite keypad/pump messages

  if (keypadActive) {

    if (
      millis() - keypadLastTime <
      KEYPAD_TIMEOUT
    ) {

      return;
    }

    keypadActive = false;
  }

  if (pumpRunning)
    return;

  lcd.clear();

  // ---------------- LINE 1 ----------------

  lcd.setCursor(0, 0);

  lcd.print("F:");

  if (fuelDistance >= 999)
    lcd.print("--");
  else
    lcd.print(fuelDistance);

  lcd.print(" T:");

  lcd.print(
    temperature,
    1
  );

  lcd.print("C");

  // ---------------- LINE 2 ----------------

  lcd.setCursor(0, 1);

  lcd.print("G:");

  lcd.print(gasValue);

  lcd.print(" ");

  if (
    currentState == SAFE
  ) {

    lcd.print("SAFE");

  } else if (
    currentState == WARNING
  ) {

    lcd.print("WARNING");

  } else {

    lcd.print("DANGER");
  }
}

// ============================================================
// EMERGENCY
// ============================================================

void handleEmergency() {

  bool currentButton =
    digitalRead(BTN_EMERGENCY);

  // Detect new press only

  if (
    lastEmergencyButton == HIGH &&
    currentButton == LOW
  ) {

    systemRunning =
      !systemRunning;

    // ---------------- STOP ----------------

    if (!systemRunning) {

      stopPump();

      stopFan();

      gateServo.write(0);

      gateOpen = false;

      gateOpening = false;

      setLEDs(
        false,
        false,
        true
      );

      tone(
        BUZZER_PIN,
        1000
      );

      lcd.clear();

      lcd.setCursor(0, 0);
      lcd.print("EMERGENCY STOP");

      lcd.setCursor(0, 1);
      lcd.print("SYSTEM OFF");
    }

    // ---------------- RESUME ----------------

    else {

      noTone(BUZZER_PIN);

      lcd.clear();

      lcd.setCursor(0, 0);
      lcd.print("SYSTEM RESUMED");

      delay(800);

      // Recalculate state

      setState(
        calculateState()
      );
    }
  }

  lastEmergencyButton =
    currentButton;
}

// ============================================================
// MAIN LOOP
// ============================================================

void loop() {

  // ==========================================================
  // 1. READ SENSORS
  // ==========================================================

  temperature =
    readTemperature();

  gasValue =
    readGas();

  fuelDistance =
    readFuelDistance();

  // ==========================================================
  // 2. GATE
  // ==========================================================

  handleGate();

  // ==========================================================
  // 3. EMERGENCY
  // ==========================================================

  handleEmergency();

  // ==========================================================
  // 4. SYSTEM STATE
  // ==========================================================

  if (systemRunning) {

    SystemState newState =
      calculateState();

    if (
      newState !=
      currentState
    ) {

      setState(newState);
    }
  }

  // ==========================================================
  // 5. FAN
  // ==========================================================

  if (systemRunning) {

    updateFan();
  }

  // ==========================================================
  // 6. PUMP
  // ==========================================================

  if (systemRunning) {

    updatePump();
  }

  // ==========================================================
  // 7. KEYPAD
  // ==========================================================

  handleKeypad();

  // ==========================================================
  // 8. LCD
  // ==========================================================

  if (
    millis() - lastLCD >=
    LCD_INTERVAL
  ) {

    lastLCD =
      millis();
if (systemRunning) {

      updateLCD();
    }
  }

  delay(10);
}
